      '--delay=600',
      '--raw',
      `--spawn-marker=${spawnMarkerPath}`,
    ], {
      cwd: request.root,
      detached: true,
      stdio: 'ignore',
    });
    child.unref();
    return { pid: child.pid ?? 0 };
  };
  const ctx = { root, scanRoot: root, store: new StoryStore(root) };
  await createHostRunHandlers(ctx, { launchWorker: launcher }).host_run({
    host: 'codex',
    agentType: 'lattice-review-quality',
    phase: 'REVIEW',
    prompt: 'foreground caller death must not own the provider worker',
    deadlineMs: 3_000,
    json: true,
  });
}

async function submitterMain(root: string, resultPath: string): Promise<void> {
  const launcher: ManagedHostRunWorkerLauncher = async request => {
    const child = spawn(process.execPath, [SELF, '--worker', request.root, request.runId, '--complete', '--delay=600'], {
      cwd: request.root,
      detached: true,
      stdio: 'ignore',
    });
    child.unref();
    return { pid: child.pid ?? 0 };
  };
  const submitted = await submitManagedHostRun(submitArgs(root, 3_000), {
    launchWorker: launcher,
    claimTimeoutMs: 1_000,
    claimPollMs: 10,
  });
  writeFileSync(resultPath, `${JSON.stringify({ runId: submitted.runId, state: submitted.state })}\n`, { mode: 0o600 });
}

function waitForExit(child: ReturnType<typeof spawn>): Promise<number | null> {
  return new Promise((resolve, reject) => {
    child.once('error', reject);
    child.once('close', code => resolve(code));
  });
}

async function main(): Promise<void> {
  const root = mkdtempSync(join(tmpdir(), 'managed-host-run-e2e-smoke-'));
  try {
    let launches = 0;
    const launcher = (crash: boolean): ManagedHostRunWorkerLauncher => async request => {
      launches += 1;
      const child = spawn(process.execPath, [SELF, '--worker', request.root, request.runId, crash ? '--crash' : '--complete'], {
        cwd: request.root,
        detached: true,
        stdio: 'ignore',
      });
      child.unref();
      return { pid: child.pid ?? 0 };
    };

    const callerDeathRoot = join(root, 'caller-death');
    const callerResultPath = join(root, 'caller-death-submission.json');
    const caller = spawn(process.execPath, [SELF, '--submitter', callerDeathRoot, callerResultPath], {
      cwd: root,
      stdio: 'ignore',
    });
    assert.equal(await waitForExit(caller), 0, 'independent submitter must exit cleanly after detached claim');
    const callerSubmission = JSON.parse(readFileSync(callerResultPath, 'utf8')) as { runId: string; state: string };
    assert.equal(callerSubmission.state, 'running', 'caller must disappear while the durable run remains active');
    const afterCallerExit = await getManagedHostRunStatus({ root: callerDeathRoot, runId: callerSubmission.runId, waitMs: 30 });
    assert.equal(afterCallerExit.run.runId, callerSubmission.runId);
    assert.ok(['running', 'completed'].includes(afterCallerExit.run.state), 'caller loss must not synthesize failure or a replacement run');
    await eventually(async () => {
      const status = await getManagedHostRunStatus({ root: callerDeathRoot, runId: callerSubmission.runId, waitMs: 30 });
      return status.run.state === 'completed';
    }, 'provider run did not survive the submitting caller process', 4_000);
    assert.equal(managedHostRunReceipt(callerDeathRoot, callerSubmission.runId).state, 'completed');

    const foregroundRoot = join(root, 'foreground-caller-death');
    const foregroundResultPath = join(root, 'foreground-caller-death-submission.json');
    const foregroundSpawnMarker = join(root, 'foreground-caller-death.spawn');
    const foregroundCaller = spawn(process.execPath, [
      SELF,
      '--foreground-caller',
      foregroundRoot,
      foregroundResultPath,
      foregroundSpawnMarker,
    ], { cwd: root, stdio: 'ignore' });
    await eventually(async () => {
      try {
        return JSON.parse(readFileSync(foregroundResultPath, 'utf8')).runId.length > 0;
      } catch {
        return false;
      }
    }, 'foreground caller did not publish the durable run identity');
    const foregroundSubmission = JSON.parse(readFileSync(foregroundResultPath, 'utf8')) as { runId: string };
    await eventually(async () => {
      const status = await getManagedHostRunStatus({ root: foregroundRoot, runId: foregroundSubmission.runId });
      return status.run.state === 'running';
    }, 'foreground caller did not observe a claimed provider worker');
    foregroundCaller.kill('SIGTERM');
    assert.notEqual(await waitForExit(foregroundCaller), 0, 'the attaching caller is deliberately terminated');
    await eventually(async () => {
      const status = await getManagedHostRunStatus({ root: foregroundRoot, runId: foregroundSubmission.runId, waitMs: 30 });
      return status.run.state === 'completed';
    }, 'foreground caller death must not terminate or replace the durable provider worker', 4_000);
    assert.equal(readFileSync(foregroundSpawnMarker, 'utf8').trim(), foregroundSubmission.runId,
      'foreground attach loss preserves exactly one provider spawn for the exact runId');
    assert.equal(managedHostRunReceipt(foregroundRoot, foregroundSubmission.runId).state, 'completed');

    const completedRoot = join(root, 'completed');
    const submitted = await submitManagedHostRun(submitArgs(completedRoot, 2_000), {
      launchWorker: launcher(false),
      claimTimeoutMs: 1_000,
      claimPollMs: 10,
    });
    assert.equal(submitted.state, 'running', 'submit returns only after the detached worker claims the run');
    assert.equal(launches, 1);

    // A fresh observer owns no child handle: the durable run directory is the only
    // join point after the submitting caller boundary has gone away.
    await eventually(async () => {
      const status = await getManagedHostRunStatus({ root: completedRoot, runId: submitted.runId, waitMs: 30 });
      return status.run.state === 'completed';
    }, 'detached OS worker did not publish terminal truth');
    assert.equal(launches, 1, 'status polling must never launch a replacement provider');
    const receipt = managedHostRunReceipt(completedRoot, submitted.runId);
    const expected = {
      providerHost: 'codex' as const,
      headHash: 'head-managed-e2e',
      materialHash: 'material-managed-e2e',
      storyFilesHash: 'story-managed-e2e',
      promptHash: 'prompt-managed-e2e',
      envelopeId: null,
      managedPromptDigest: `sha256:${createHash('sha256').update('detached real worker review prompt').digest('hex')}`,
    };
    const binding = createManagedReviewEvidenceBinding({
      root: completedRoot,
      storyId: 'B-managed-e2e',
      providerAgent: 'lattice-review-quality',
      lane: 'lattice-review-quality',
      reviewRunId: 'B-managed-e2e:RR-001',
      runId: submitted.runId,
      receiptId: receipt.receiptId,
      expected,
    });
    assert.equal(verifyManagedReviewEvidence({
      root: completedRoot,
      storyId: 'B-managed-e2e',
      agent: 'lattice-review-quality',
      lane: 'lattice-review-quality',
      reviewRunId: 'B-managed-e2e:RR-001',
      binding: binding.binding,
      expected,
    }).valid, true, 'the exact detached-worker receipt must be admissible to the formal reviewer consumer');

    const crashedRoot = join(root, 'crashed');
    const crashed = await submitManagedHostRun(submitArgs(crashedRoot, 500), {
      launchWorker: launcher(true),
      claimTimeoutMs: 1_000,
      claimPollMs: 10,
    });
    const crashedDeadlineAt = Date.parse(crashed.deadlineAt);
    assert.ok(Number.isFinite(crashedDeadlineAt), 'crashed worker exposes a parseable absolute deadline');
    const beforeCrashDeadline = await getManagedHostRunStatus({
      root: crashedRoot,
      runId: crashed.runId,
      waitMs: 0,
      now: () => crashedDeadlineAt - 1,
    });
    assert.equal(beforeCrashDeadline.run.runId, crashed.runId);
    assert.equal(beforeCrashDeadline.run.state, 'running', 'post-claim worker death before deadline preserves the original run identity instead of replacing it');
    const deadlineGrace = await getManagedHostRunStatus({
      root: crashedRoot,
      runId: crashed.runId,
      waitMs: 0,
      now: () => crashedDeadlineAt,
    });
    assert.equal(deadlineGrace.run.state, 'running', 'the exact deadline begins the production cooperative cleanup grace');
    const reconciled = await getManagedHostRunStatus({
      root: crashedRoot,
      runId: crashed.runId,
      waitMs: 0,
      now: () => crashedDeadlineAt + 300,
    });
    assert.equal(reconciled.run.state, 'timed_out', 'a crashed worker converges after the finite deadline cleanup grace');
    assert.ok(reconciled.run.terminal, 'crashed worker reconciliation must publish definite terminal truth');
    assert.equal(reconciled.run.terminal.reason, 'absolute_deadline_exceeded');

    const raceRoot = join(root, 'status-cancel-deadline-race');
    const raced = await submitManagedHostRun(submitArgs(raceRoot, 150), {
      launchWorker: launcher(false),
      claimTimeoutMs: 1_000,
      claimPollMs: 10,
    });
    await new Promise(resolve => setTimeout(resolve, 95));
    const racingTouches = await Promise.all([
      getManagedHostRunStatus({ root: raceRoot, runId: raced.runId, afterGeneration: raced.generation, waitMs: 300 }),
      cancelManagedHostRun({ root: raceRoot, runId: raced.runId, reason: 'status/attach/cancel deadline race' }),
      getManagedHostRunStatus({ root: raceRoot, runId: raced.runId, waitMs: 300 }),
    ]);
    await eventually(async () => (await getManagedHostRunStatus({ root: raceRoot, runId: raced.runId })).run.terminal !== null,
      'status/cancel/deadline race did not converge on terminal truth');
    const raceReceipt = managedHostRunReceipt(raceRoot, raced.runId);
    const raceTerminalPath = join(managedHostRunDirectory(raceRoot, raced.runId), 'terminal.json');
    const immutableTerminal = readFileSync(raceTerminalPath);
    const converged = await Promise.all([
      getManagedHostRunStatus({ root: raceRoot, runId: raced.runId }),
      getManagedHostRunStatus({ root: raceRoot, runId: raced.runId, waitMs: 300 }),
      cancelManagedHostRun({ root: raceRoot, runId: raced.runId, reason: 'late losing cancel' }),
    ]);
    for (const value of [...racingTouches, ...converged]) {
      const projection = 'run' in value ? value.run : value;
      if (projection.terminal) {
        assert.equal(managedHostRunReceipt(raceRoot, raced.runId).receiptId, raceReceipt.receiptId,
          'all terminal observers converge on the exact immutable receipt digest');
      }
    }
    assert.deepEqual(readFileSync(raceTerminalPath), immutableTerminal, 'late status/cancel/reconcile touches cannot rewrite terminal bytes');

    console.log('managed-host-run-e2e-smoke PASS');
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
}

if (process.argv[2] === '--worker') {
  const delayArg = process.argv.find(value => value.startsWith('--delay='));
  const markerArg = process.argv.find(value => value.startsWith('--spawn-marker='));
  workerMain(
    process.argv[3] ?? '',
    process.argv[4] ?? '',
    process.argv[5] === '--crash',
    delayArg ? Number(delayArg.slice('--delay='.length)) : 120,
    !process.argv.includes('--raw'),
    markerArg ? markerArg.slice('--spawn-marker='.length) : undefined,
  )
    .catch(error => {
      console.error(error instanceof Error ? error.stack : String(error));
      process.exitCode = 1;
    });
} else if (process.argv[2] === '--submitter') {
  submitterMain(process.argv[3] ?? '', process.argv[4] ?? '')
    .catch(error => {
      console.error(error instanceof Error ? error.stack : String(error));
      process.exitCode = 1;
    });
} else if (process.argv[2] === '--foreground-caller') {
  foregroundCallerMain(process.argv[3] ?? '', process.argv[4] ?? '', process.argv[5] ?? '')
    .catch(error => {
      console.error(error instanceof Error ? error.stack : String(error));
      process.exitCode = 1;
    });
} else {
  main().catch(error => {
    console.error(error instanceof Error ? error.stack : String(error));
    process.exitCode = 1;
  });
}
import { isAbsolute, relative } from 'node:path';
import { posix } from 'node:path';
import { digestCanonicalJson } from './digest.js';
import type {
  ReviewerReadDiagnostic,
  ReviewerReadLogEvent,
  ReviewerReadLogEvidence,
  ReviewerReadManifest,
} from './types.js';
import { isRegisteredReviewAgent } from './agent-dispatch-registry.js';

export interface ReviewerReadLogOptions {
  projectRoot?: string;
  requirementsDir?: string;
}

export interface ReviewerReadCaptureContext extends ReviewerReadLogOptions {
  agent?: string | null;
}

type ReadMode = ReviewerReadLogEvent['mode'];

const DEFAULT_REQUIREMENTS_DIR = 'docs/requirements';
const CONTROL_CHARS = /[\u0000-\u001f\u007f]/;
const SHA256_HEX = /^[a-f0-9]{64}$/;
const REVIEWER_READ_DIAGNOSTIC_CODES: readonly ReviewerReadDiagnostic['code'][] = [
  'read_manifest_missing_full_read',
  'read_manifest_extra_full_read',
  'read_manifest_missing_triage',
  'read_manifest_extra_triage',
  'full_scan_without_scanEscalationReason',
] as const;

function rejectPath(label: string, reason: string, value: unknown): never {
  throw new Error(`${label}: ${reason} (${JSON.stringify(value)})`);
}

function normalizeRelativePath(value: unknown, label: string): string {
  if (typeof value !== 'string') rejectPath(label, 'path must be a string', value);
  const raw = value.trim();
  if (!raw) rejectPath(label, 'path must be non-empty', value);
  if (CONTROL_CHARS.test(raw)) rejectPath(label, 'path contains control characters', value);
  if (raw.includes('\\')) rejectPath(label, 'path must use POSIX / separators', value);
  if (isAbsolute(raw) || /^[A-Za-z]:[\\/]/.test(raw)) rejectPath(label, 'absolute paths are not allowed', value);
  if (/^[A-Za-z][A-Za-z0-9+.-]*:\/\//.test(raw)) rejectPath(label, 'URL paths are not allowed', value);
  if (raw.startsWith('~')) rejectPath(label, 'home-relative paths are not allowed', value);
  const normalized = posix.normalize(raw);
  if (normalized === '.' || normalized === '..' || normalized.startsWith('../') || normalized.includes('/../')) {
    rejectPath(label, 'path traversal is not allowed', value);
  }
  return normalized.replace(/^\.\//, '');
}

function normalizePathArray(input: unknown, field: string, label: string): string[] {
  if (!Array.isArray(input)) {
    throw new Error(`${label}.${field}: must be an array of relative file paths`);
  }
  const seen = new Set<string>();
  const normalized = input.map((item, idx) => {
    const rel = normalizeRelativePath(item, `${label}.${field}[${idx}]`);
    if (seen.has(rel)) {
      throw new Error(`${label}.${field}: duplicate path ${rel}`);
    }
    seen.add(rel);
    return rel;
  });
  return normalized.sort((a, b) => a.localeCompare(b));
}

function normalizeManifestPathArray(input: unknown, field: keyof ReviewerReadManifest, label: string): string[] {
  return normalizePathArray(input, field, label);
}

export function normalizeReviewerReadManifest(input: unknown, label = 'readManifest'): ReviewerReadManifest {
  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    throw new Error(`${label}: must be an object with filesReadFully, filesTriagedByName, and scanEscalationReason`);
  }
  const record = input as Record<string, unknown>;
  if (!Object.prototype.hasOwnProperty.call(record, 'filesReadFully')) {
    throw new Error(`${label}.filesReadFully: missing required array`);
  }
  if (!Object.prototype.hasOwnProperty.call(record, 'filesTriagedByName')) {
    throw new Error(`${label}.filesTriagedByName: missing required array`);
  }
  if (!Object.prototype.hasOwnProperty.call(record, 'scanEscalationReason')) {
    throw new Error(`${label}.scanEscalationReason: missing required string|null`);
  }

  const filesReadFully = normalizeManifestPathArray(record.filesReadFully, 'filesReadFully', label);
  const filesTriagedByName = normalizeManifestPathArray(record.filesTriagedByName, 'filesTriagedByName', label);
  const all = new Set(filesReadFully);
  for (const path of filesTriagedByName) {
    if (all.has(path)) {
      throw new Error(`${label}: duplicate path ${path} appears in both filesReadFully and filesTriagedByName`);
    }
    all.add(path);
  }

  let scanEscalationReason: string | null;
  if (record.scanEscalationReason === null) {
    scanEscalationReason = null;
  } else if (typeof record.scanEscalationReason === 'string') {
    const trimmed = record.scanEscalationReason.trim();
    if (!trimmed) {
      throw new Error(`${label}.scanEscalationReason: use null when there is no escalation reason; blank strings are malformed`);
    }
    scanEscalationReason = trimmed;
  } else {
    throw new Error(`${label}.scanEscalationReason: must be a string or null`);
  }

  const optionalDigest = (field: 'candidateSpecSetDigest' | 'corpusDigest'): string | undefined => {
    const value = record[field];
    if (value === undefined) return undefined;
    if (typeof value !== 'string' || !/^(?:sha256:)?[a-f0-9]{64}$/.test(value.trim())) {
      throw new Error(`${label}.${field}: must be a sha256 digest when supplied`);
    }
    return value.trim().replace(/^sha256:/, '');
  };
  const candidateSpecSetDigest = optionalDigest('candidateSpecSetDigest');
  const corpusDigest = optionalDigest('corpusDigest');
  return {
    filesReadFully,
    filesTriagedByName,
    scanEscalationReason,
    ...(candidateSpecSetDigest ? { candidateSpecSetDigest } : {}),
    ...(corpusDigest ? { corpusDigest } : {}),
  };
}

export function digestReviewerReadManifest(manifest: ReviewerReadManifest): string {
  return digestCanonicalJson({
    version: 1,
    readManifest: normalizeReviewerReadManifest(manifest),
  });
}

function normalizeRequirementsDir(requirementsDir: string | undefined): string {
  return normalizeRelativePath(requirementsDir || DEFAULT_REQUIREMENTS_DIR, 'requirementsDir');
}

function normalizeReadLogPath(value: unknown, options: ReviewerReadLogOptions, label: string): string {
  if (typeof value !== 'string') rejectPath(label, 'path must be a string', value);
  let raw = value.trim();
  if (isAbsolute(raw)) {
    if (!options.projectRoot) rejectPath(label, 'absolute paths require projectRoot for relativization', value);
    const rel = relative(options.projectRoot, raw).replace(/\\/g, '/');
    if (rel.startsWith('../') || rel === '..' || isAbsolute(rel)) {
      rejectPath(label, 'absolute path is outside projectRoot', value);
    }
    raw = rel;
  }
  return normalizeRelativePath(raw, label);
}

export function isDecisionMarkdownPath(path: string, options: ReviewerReadLogOptions = {}): boolean {
  const requirementsDir = normalizeRequirementsDir(options.requirementsDir);
  const prefix = `${requirementsDir}/decisions/`;
  if (!path.startsWith(prefix) || !path.endsWith('.md')) return false;
  const rest = path.slice(prefix.length);
  return rest.length > 0 && !rest.includes('/');
}

function rawPathFromEvent(input: Record<string, unknown>): unknown {
  return input.path ?? input.filePath ?? input.file ?? input.absolutePath ?? input.relPath;
}

function readModeFromEvent(input: Record<string, unknown>): ReadMode {
  if (input.readFully === false) return 'triage';
  if (input.readFully === true) return 'full';
  const raw = input.mode ?? input.action ?? input.kind ?? input.readType;
  if (typeof raw === 'string') {
    const mode = raw.trim().toLowerCase();
    if (['triage', 'triaged', 'filename', 'name', 'list', 'glob'].includes(mode)) return 'triage';
    if (['full', 'read', 'readfull', 'read_full', 'tool:read', 'read-tool'].includes(mode)) return 'full';
  }
  return 'full';
}

function tokenCountFromEvent(input: Record<string, unknown>): number | null {
  const raw = input.tokenCount ?? input.tokens;
  if (raw === undefined || raw === null) return null;
  if (typeof raw === 'number' && Number.isFinite(raw) && raw >= 0) return Math.trunc(raw);
  return null;
}

export function captureReviewerReadEvent(
  input: unknown,
  context: ReviewerReadCaptureContext = {},
): ReviewerReadLogEvent | null {
  if (!isRegisteredReviewAgent(context.agent)) return null;
  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    throw new Error('read event: must be an object');
  }
  const record = input as Record<string, unknown>;
  const path = normalizeReadLogPath(rawPathFromEvent(record), context, 'read event.path');
  if (!isDecisionMarkdownPath(path, context)) return null;
  return {
    path,
    mode: readModeFromEvent(record),
    tokenCount: tokenCountFromEvent(record),
    agent: context.agent!,
  };
}

export function normalizeReviewerReadLog(events: readonly ReviewerReadLogEvent[]): ReviewerReadLogEvidence {
  const full = new Set<string>();
  const triage = new Set<string>();
  const fullEvents: Array<{ path: string; mode: ReadMode; tokenCount: number | null }> = [];
  const digestEvents: Array<{ path: string; mode: ReadMode; tokenCount: number | null }> = [];

  for (const event of events) {
    const path = normalizeRelativePath(event.path, 'readLog.event.path');
    const mode = event.mode === 'triage' ? 'triage' : 'full';
    const tokenCount = typeof event.tokenCount === 'number' && Number.isFinite(event.tokenCount) && event.tokenCount >= 0
      ? Math.trunc(event.tokenCount)
      : null;
    if (mode === 'full') {
      full.add(path);
      fullEvents.push({ path, mode, tokenCount });
    } else {
      triage.add(path);
    }
    digestEvents.push({ path, mode, tokenCount });
  }

  const filesReadFully = [...full].sort((a, b) => a.localeCompare(b));
  const filesTriagedByName = [...triage]
    .filter(path => !full.has(path))
    .sort((a, b) => a.localeCompare(b));
  const hasCompleteTokenCounts = fullEvents.length > 0 && fullEvents.every(event => event.tokenCount !== null);
  const tokenCount = hasCompleteTokenCounts
    ? fullEvents.reduce((sum, event) => sum + (event.tokenCount ?? 0), 0)
    : null;
  const summary = {
    readCount: fullEvents.length,
    tokenCount,
  };
  const normalizedDigestEvents = digestEvents.sort((a, b) =>
    `${a.mode}:${a.path}:${a.tokenCount ?? 'null'}`.localeCompare(`${b.mode}:${b.path}:${b.tokenCount ?? 'null'}`),
  );
  const digest = digestCanonicalJson({
    version: 1,
    filesReadFully,
    filesTriagedByName,
    summary,
    events: normalizedDigestEvents,
  });
  return { filesReadFully, filesTriagedByName, summary, digest };
}

export function normalizeReviewerReadLogEvidence(input: unknown, label = 'readLog'): ReviewerReadLogEvidence {
  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    throw new Error(`${label}: must be an object with filesReadFully, filesTriagedByName, summary, and digest`);
  }
  const record = input as Record<string, unknown>;
  const filesReadFully = normalizePathArray(record.filesReadFully, 'filesReadFully', label);
  const filesTriagedByName = normalizePathArray(record.filesTriagedByName, 'filesTriagedByName', label);
  const full = new Set(filesReadFully);
  for (const path of filesTriagedByName) {
    if (full.has(path)) {
      throw new Error(`${label}: duplicate path ${path} appears in both filesReadFully and filesTriagedByName`);
    }
  }
  if (!record.summary || typeof record.summary !== 'object' || Array.isArray(record.summary)) {
    throw new Error(`${label}.summary: must be an object with readCount and tokenCount`);
  }
  const summaryRecord = record.summary as Record<string, unknown>;
  const readCount = summaryRecord.readCount;
  if (typeof readCount !== 'number' || !Number.isInteger(readCount) || readCount < 0) {
    throw new Error(`${label}.summary.readCount: must be a non-negative integer`);
  }
  const rawTokenCount = summaryRecord.tokenCount;
  if (
    rawTokenCount !== null
    && (typeof rawTokenCount !== 'number' || !Number.isInteger(rawTokenCount) || rawTokenCount < 0)
  ) {
    throw new Error(`${label}.summary.tokenCount: must be a non-negative integer or null`);
  }
  if (typeof record.digest !== 'string' || !SHA256_HEX.test(record.digest)) {
    throw new Error(`${label}.digest: must be a sha256 hex digest`);
  }
  const tokenCount = rawTokenCount === null ? null : rawTokenCount;
  return {
    filesReadFully,
    filesTriagedByName,
    summary: {
      readCount,
      tokenCount,
    },
    digest: record.digest,
  };
}

export function normalizeReviewerReadDiagnostics(input: unknown, label = 'readDiagnostics'): ReviewerReadDiagnostic[] {
  if (!Array.isArray(input)) {
    throw new Error(`${label}: must be an array`);
  }
  const normalized = input.map((item, idx): ReviewerReadDiagnostic => {
    if (!item || typeof item !== 'object' || Array.isArray(item)) {
      throw new Error(`${label}[${idx}]: must be an object`);
    }
    const record = item as Record<string, unknown>;
    if (typeof record.code !== 'string' || !(REVIEWER_READ_DIAGNOSTIC_CODES as readonly string[]).includes(record.code)) {
      throw new Error(`${label}[${idx}].code: unsupported reviewer read diagnostic code`);
    }
    if (record.severity !== 'finding') {
      throw new Error(`${label}[${idx}].severity: must be "finding"`);
    }
    if (typeof record.message !== 'string' || record.message.trim().length === 0) {
      throw new Error(`${label}[${idx}].message: must be a non-empty string`);
    }
    const path = record.path === undefined
      ? undefined
      : normalizeRelativePath(record.path, `${label}[${idx}].path`);
    return {
      code: record.code as ReviewerReadDiagnostic['code'],
      severity: 'finding',
      message: record.message.trim(),
      ...(path ? { path } : {}),
    };
  });
  return normalized.sort((a, b) =>
    `${a.code}:${a.path ?? ''}:${a.message}`.localeCompare(`${b.code}:${b.path ?? ''}:${b.message}`),
  );
}

function addSetDiagnostics(
  diagnostics: ReviewerReadDiagnostic[],
  expected: readonly string[],
  actual: readonly string[],
  missingCode: ReviewerReadDiagnostic['code'],
  extraCode: ReviewerReadDiagnostic['code'],
  missingMessage: string,
  extraMessage: string,
): void {
  const expectedSet = new Set(expected);
  const actualSet = new Set(actual);
  for (const path of [...expectedSet].sort((a, b) => a.localeCompare(b))) {
    if (!actualSet.has(path)) {
      diagnostics.push({ code: missingCode, severity: 'finding', path, message: `${missingMessage}: ${path}` });
    }
  }
  for (const path of [...actualSet].sort((a, b) => a.localeCompare(b))) {
    if (!expectedSet.has(path)) {
      diagnostics.push({ code: extraCode, severity: 'finding', path, message: `${extraMessage}: ${path}` });
    }
  }
}

function decisionMarkdownPaths(paths: readonly string[], requirementsDir: string | undefined): string[] {
  return paths
    .filter(path => isDecisionMarkdownPath(path, { requirementsDir }))
    .sort((a, b) => a.localeCompare(b));
}

export function diagnoseReviewerReadEvidence(args: {
  readManifest: ReviewerReadManifest;
  readLog: ReviewerReadLogEvidence;
  knownDecisionFiles?: string[];
  requirementsDir?: string;
}): ReviewerReadDiagnostic[] {
  const readManifest = normalizeReviewerReadManifest(args.readManifest);
  const diagnostics: ReviewerReadDiagnostic[] = [];
  const readLogFilesReadFully = decisionMarkdownPaths(args.readLog.filesReadFully, args.requirementsDir);
  const readLogFilesTriagedByName = decisionMarkdownPaths(args.readLog.filesTriagedByName, args.requirementsDir);
  const manifestFilesReadFully = decisionMarkdownPaths(readManifest.filesReadFully, args.requirementsDir);
  const manifestFilesTriagedByName = decisionMarkdownPaths(readManifest.filesTriagedByName, args.requirementsDir);
  addSetDiagnostics(
    diagnostics,
    readLogFilesReadFully,
    manifestFilesReadFully,
    'read_manifest_missing_full_read',
    'read_manifest_extra_full_read',
    'mechanical decisions-doc read log has a full read missing from readManifest.filesReadFully',
    'readManifest.filesReadFully self-reports a decisions-doc file absent from the mechanical read log',
  );
  addSetDiagnostics(
    diagnostics,
    readLogFilesTriagedByName,
    manifestFilesTriagedByName,
    'read_manifest_missing_triage',
    'read_manifest_extra_triage',
    'mechanical decisions-doc read log has a triaged file missing from readManifest.filesTriagedByName',
    'readManifest.filesTriagedByName self-reports a decisions-doc file absent from the mechanical read log',
  );

  const knownDecisionFiles = (args.knownDecisionFiles ?? [])
    .map((path, idx) => normalizeRelativePath(path, `knownDecisionFiles[${idx}]`))
    .filter(path => isDecisionMarkdownPath(path, { requirementsDir: args.requirementsDir }))
    .sort((a, b) => a.localeCompare(b));
  const fullyRead = new Set(readLogFilesReadFully);
  const fullScanWithoutReason = knownDecisionFiles.length > 0
    && knownDecisionFiles.every(path => fullyRead.has(path))
    && readManifest.scanEscalationReason === null;
  if (fullScanWithoutReason) {
    diagnostics.push({
      code: 'full_scan_without_scanEscalationReason',
      severity: 'finding',
      message: 'Full decisions-doc scan was mechanically observed but readManifest.scanEscalationReason is null',
    });
  }
  return diagnostics;
}
# Managed cross-provider CLI execution

Status: Adopted
Story: B-137a
Date: 2026-08-14

## Context

When a Claude host started Codex (or a Codex host started Claude) with raw shell
execution, the caller owned the child process implicitly. A caller watchdog,
terminal disconnect, or ten-minute foreground boundary could end observation
without proving that the provider had failed. Treating that loss of observation
as failure caused duplicate reviewer launches; treating `running` forever as
proof of health caused unbounded waits. Output silence alone answers neither
question.

Proofbound is host-neutral. Native Codex/Claude subagent lifecycle APIs are not
portable and therefore are not the execution contract. This decision covers
only Proofbound-owned cross-provider CLI processes.

## Decision

Proofbound owns every public `host_run` and every formal cross-provider CLI
reviewer launch through a durable `ManagedHostRun`. General provider workloads
such as planned steps and autopilot repair keep their existing bounded adapters
but share the mandatory provider-process admission registry; they do not claim
durable reviewer ownership or reviewer evidence. The caller submits and
observes; a detached worker owns the managed provider process until an exclusive
terminal record exists.

The public surface is:

- `host_run`: submit, optionally attach in foreground, or return after claim
  with `--detach`;
- `host_run_status`: read or long-poll one run for at most 30 seconds;
- `host_run_cancel`: idempotently request cancellation;
- `host_run_worker`: private runtime continuation, dispatchable internally but
  hidden from ordinary help/catalog discovery;
- `managed_review_proposal_set`: compatibility-only provider callback for older
  adapters, not the formal managed happy path;
- `managed_review_evidence_import`: verdict-free exact-receipt importer.

`cross_host_review` remains the policy/profile owner for paired host verdicts,
but its Codex leaf executes inside ManagedHostRun and exposes the managed run
and receipt in host-B provenance.

## State and liveness contract

The states are `submitted`, `running`, `completed`, `failed`, `cancelled`, and
`timed_out`. Exactly one terminal file wins by exclusive creation. Repeated
status, cancel and resume operations are idempotent and never create a new run.

Two clocks are deliberately distinct:

- `workerHeartbeatAt` shows that the supervisor can still update its durable
  snapshot;
- `lastProviderProgressAt` changes only when observable provider stdout/stderr
  arrives.

Neither clock is a completion oracle. A provider may legitimately be silent,
and a worker heartbeat does not prove provider progress. Expiry of a 30-second
observation wait is non-terminal: it only wakes the caller and never authorizes
a retry. The `host_run_status` call is also the run's next-touch reconciler,
however, so during that call an already-requested cancellation or an expired
absolute deadline can legitimately publish the corresponding `cancelled` or
`timed_out` terminal state.

Every run has a finite absolute deadline (30 minutes by default, bounded to 24
hours). Deadline or cancellation reconciliation performs bounded TERM, KILL,
reap and residual probing. Replacement is safe only when cleanup facts prove
there is no residual process group. Ambiguous PID/PGID identity remains
`replacementSafe=false`; it is not guessed away.

## Persistence and process ownership

Each run has a 0700 directory at
`<primary-worktree>/.lattice/runtime/host-runs/<runId>/`. Resolving to the
primary worktree keeps the run observable after a Story worktree is removed at
DONE. Immutable spec and digest-only owner data, snapshot, append-only events,
bounded live output, result and terminal receipt are durable. Live output is
capped at 8 MiB per run and reports truncation instead of growing without bound.
Prompt, capability and optional redacted environment are 0600 one-shot inputs;
the worker validates and deletes them before provider launch. Only root and
runId cross the detached-worker argv boundary.

On POSIX the provider runs in an isolated process group. Codex receives the
prompt through documented stdin (`codex exec ... -`). Claude receives a 0600
one-shot prompt file below the exact provider cwd's ignored
`.lattice/runtime/host-run-prompts/` tree, because Claude's workspace sandbox
rejects an otherwise protected OS-temp prompt outside that cwd. Prompt text never
enters argv and the private leaf is removed after settlement. A detached formal
Claude reviewer has no approval terminal, so only the signed `managed_reviewer`
profile launches it with `--permission-mode bypassPermissions`; ordinary Claude
host runs retain their configured policy, and the strict final proposal/parser
boundary is unchanged. The current agy print launcher accepts prompt text only
in argv, so managed agy execution refuses before provider spawn until agy
exposes a stdin or protected prompt-file transport. Unsupported platforms
likewise refuse before provider spawn rather than pretending child-only cleanup
is equivalent.

## Shared provider admission

Provider capacity is owned by `core/provider-process-registry.ts`, independent
of the usage ledger. All Proofbound-owned provider workloads acquire an atomic,
token-owned slot under `.lattice/runtime/provider-process-slots/` before spawn.
Turning off `LATTICE_USAGE_LEDGER` disables usage rows and budget accounting,
not process admission.

A live recorded pid is never reclaimed because of age. Dead pids are
reclaimable; corrupt/ownerless slots use a bounded stale backstop. Release
checks the acquire token so a late old holder cannot delete a slot that has
already been reclaimed and reassigned.

Low-level provider adapter modules remain `adapter_only`: their caller owns
admission. Readiness/version probes are classified separately and do not become
review evidence.

### Provider execution surface classification

Every production provider spawn site is classified by
`ProviderExecutionSurfaceStatus` (`packages/main/src/core/provider-process-registry.ts`),
and `packages/main/src/tasks/provider-execution-inventory-contract.ts` fails if a
new spawn path appears without one:

| Status | Meaning |
|---|---|
| `managed` | Executes through ManagedHostRun: durable run identity, supervised process group, absolute deadline, exactly one terminal receipt. |
| `admission_only` | Not managed-executed, but routed through the shared provider admission boundary, so the concurrency cap and slot accounting still apply. |
| `adapter_only` | A low-level adapter module whose *caller* owns admission; the adapter itself makes no gate claim. |
| `readiness_probe` | Version/readiness probing only. Never becomes review evidence. |
| `legacy_unmanaged` | A provider spawn that is neither managed nor admission-routed. **Reserved, and currently empty by contract.** |

`admission_managed` is not a status value: admission and managed execution are
two separate properties, expressed by `admission_only` (admission without
managed execution) and `managed` (both).

The `legacy_unmanaged` bucket exists so an unmanaged spawn path must be declared
rather than pass silently. It is asserted empty — `provider-execution-inventory-contract.ts`
requires that no surface carries it — so adding one is a deliberate, reviewable
act that fails the contract until justified. It is not a claim that unmanaged
execution is impossible, only that none is currently admitted.

## Formal managed reviewer evidence

Native-host reviewers retain the existing signed ReviewRun plus direct
ReviewPass/Finding flow. A cross-provider CLI reviewer uses a two-phase flow:

1. The controller creates the signed ReviewRun.
2. `host_run --managedReview` derives the exact assembled prompt and seals
   story, provider, lane, ReviewRun, head, material, story-files and prompt
   bindings.
3. The managed prompt requires the provider's final assistant result to be one
   bounded `lattice.managed_review_final_proposal.v1` JSON envelope with
   pass-or-findings and truthful read evidence. It cannot write final
   `review_pass_set`/`finding_add` evidence from inside the managed run. After a
   successful provider exit, the owning adapter selects only Codex's terminal
   `item.completed` `agent_message` or Claude's successful terminal
   provider-validated `structured_output` (`type=result`, `subtype=success`,
   field present). Claude non-success result events, success events without
   `structured_output`, and `event.result` are ignored. Claude's signed
   managed-review launch supplies a bounded non-secret `--json-schema` bound
   to the exact story/provider/lane/ReviewRun tuple. Tool logs, arbitrary
   stdout, Claude prose or fenced JSON, and controller fields are never
   proposal inputs. The worker
   validates the same tuple and atomically writes the immutable proposal.
   Missing, malformed, multiple or oversized final envelopes fail the managed
   run closed. The older descriptor-authorized
   `managed_review_proposal_set` callback remains compatibility-only.
4. Successful terminal creation seals spec, proposal, result, live-output and
   event-journal digests plus cleanup facts.
5. The controller calls `managed_review_evidence_import` with only the exact
   runId and receiptId. It cannot provide or alter verdict bytes. Import still
   fails closed unless the completed receipt proves `replacementSafe=true`,
   `processCleanup.reaped=true`, and
   `processCleanup.residualProcessGroup=false`.
6. The importer preserves provider reviewer/lane/ReviewRun/read provenance and
   writes the existing signed ReviewPass/Finding shape.
7. Import time and the REVIEW gate both call the shared Proof Admissibility
   registry/intake/evaluator and revalidate the current terminal, proposal,
   journal, prompt and material tuple.

Raw CLI output outside the trusted final-result adapter lane, usage-ledger rows, time-window correlations, pre-terminal
proposals, failed/cancelled/timed-out terminals and controller-authored verdicts
cannot upgrade to managed reviewer evidence. Raw same-UID CLI calls, forged
environment values, stale process groups, terminal/reaped runs and
ambiguous/multiple active candidates cannot borrow the descriptor authority.

The worker's reserved durable cancellation reason
`absolute_deadline_exceeded` always reconciles to a `timed_out` terminal with
that exact reason, even if the next observation occurs through the cancellation
branch. Human/operator cancellation remains `cancelled`; both paths retain the
same cleanup and replacement-safety proof.

The authority classifications remain disjoint. A native-host reviewer keeps the
signed ReviewRun plus direct ReviewPass/Finding path only when a registered
host-adapter broker signs the exact closeout invocation. Its Ed25519 attestation
binds Story, agent/lane, ReviewRun, writer session, signed dispatch,
adapter/host identity and a one-shot nonce. Lattice stores the registered public
key and nonce-consumption record, but exposes no issuer command and stores no
broker private key. `dispatch`, `review_run_start`, inherited environment values
and raw provider CLIs cannot mint this authority. The host adapter must inject
the signed attestation over a dedicated descriptor for the exact CLI process;
without that integration, native direct evidence is advisory-only and formal
review must use the managed path.

Process ancestry is secondary evidence. An unobservable process table, as in a
brokered desktop sandbox, does not negate a valid broker signature. When a full
ancestry is observable, any mixed distinct provider families (Claude→Codex or
Codex→Claude) veto direct evidence even if the nearest ancestor matches. The
one-shot local nonce ledger prevents replay but is not represented as protection
against a same-UID/root attacker capable of replacing trusted configuration or
instrumenting the broker.

A cross-provider CLI reviewer requires a managed terminal receipt;
cross-provider CLI output without that receipt is advisory-only. An explicit
`degraded-single-host` fallback is local DONE assurance through host-verdict
evidence, not direct or managed REVIEW evidence, and cannot borrow either
reviewer authority path.

## Operator guidance

`lattice dispatch` prints two explicit execution modes. A native subagent uses
its host lifecycle. A cross-provider CLI reviewer must use `host_run
--managedReview`; raw `bash + codex/claude/agy` is advisory-only and cannot
satisfy the managed evidence path.

Poll the same run with `host_run_status --waitMs 30000`. Continue observing the
same run across silent intervals. Cancel only on an explicit operator decision.
Start a replacement only after an authoritative terminal and only when its
cleanup proves replacement safety.

## Retention and trust boundary

`lattice doctor` reports worker liveness, provider-progress observability,
deadline/cancel state, residuals, replacement safety and retention. Explicit
`doctor --repair` garbage-collects heavy terminal run directories only beyond
90 days and first revalidates sealed spec, result, event-journal, proposal and
evidence-binding digests, then archives the sealed receipt, evidence-binding
digest, binding projection, provider-authored proposal body, and import-seal
pair (evidence-binding.json + evidence-binding.seal.json) under
`.lattice/runtime/host-run-receipts/`. On recover, the proposal body is
re-digested against the sealed receipt's evidenceProposalDigest, the binding
body is re-digested against the archive's evidenceBindingDigest, and the
archived seal's schemaVersion, runId, and bindingDigest are checked the same
way as the live path. Heavy live-output and result provider text are not
retained. Pre-F-127 archives that lack the later capture fields refuse closed
rather than reconstructing missing bodies. Any mismatch is reported as corrupt
and retained for manual review. GC does not treat a receiptId match as
sufficient: an incomplete leftover is atomically replaced from still-valid
live artifacts, and if neither the existing archive nor the live runtime can
form a complete capture, the live directory is retained. The import-time evidence-binding seal is
checked before GC, and an expired cross-host run removes only its canonical
temporary detached snapshot. Active or corrupt runs and
runs that still contain one-shot inputs are retained fail-closed. Failed startup
removes one-shot secrets immediately.

The local filesystem boundary does not defend against a same-UID or root
attacker. Retained output may contain sensitive provider text and must be
treated accordingly.

## Compatibility and non-goals

- Existing finite provider timeouts, cross-host policy ceilings, bounded retry
  and fail-closed classifications remain in force.
- Ordinary non-review host runs remain compatible but now gain durable
  ownership and shared admission.
- No remote scheduler, daemon, queue or native-host subagent abstraction is
  introduced.
- Usage diagnostics remain non-authoritative and never become lifecycle proof.
